import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for sqlite3 import
found_sqlite = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'sqlite3' for name in node.names):
        found_sqlite = True

if not found_sqlite:
    raise AssertionError('Task 1: Missing import sqlite3')

# Check for with statement
found_with = False
for node in ast.walk(tree):
    if isinstance(node, ast.With):
        found_with = True

if not found_with:
    raise AssertionError('Task 1: Missing with statement')

# Check for CREATE TABLE statement
found_create = False
code_str = user_code.upper()
if 'CREATE TABLE' in code_str and 'PRODUCTS' in code_str and 'PRIMARY KEY' in code_str:
    found_create = True

if not found_create:
    raise AssertionError('Task 2: Missing CREATE TABLE statement with PRIMARY KEY')

# Check for .execute() call (single insert)
found_execute = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'execute':
        found_execute = True

if not found_execute:
    raise AssertionError('Task 3: Missing .execute() call for single insert')

# Check for .executemany() call
found_executemany = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'executemany':
        found_executemany = True

if not found_executemany:
    raise AssertionError('Task 4: Missing .executemany() call')

# Check for commit() call
found_commit = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'commit':
        found_commit = True

if not found_commit:
    raise AssertionError('Task 5: Missing .commit() call')

# Check for print statement
found_print = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'print':
        found_print = True

if not found_print:
    raise AssertionError('Task 5: Missing print statement')

print('TEST_PASSED')
